template:
struct Response {
    code: u16,
    payload: String,
    latency_ms: u64,
}

fn status(r: Response) -> &'static str {
    match r {
        Response { code: 200, ⟦rest1⟧ } => "ok",
        Response { code: 404, ⟦rest2⟧ } => "not found",
        _ => "error",
    }
}

fn main() {
    let r = Response { code: 200, payload: String::new(), latency_ms: 1 };
    println!("{}", status(r));
}

tests:
#[test]
fn tests_status() {
    assert_eq!(status(Response { code: 200, payload: String::from("a"), latency_ms: 5 }), "ok");
    assert_eq!(status(Response { code: 404, payload: String::from("b"), latency_ms: 10 }), "not found");
    assert_eq!(status(Response { code: 500, payload: String::from("c"), latency_ms: 1 }), "error");
}
